entries.yaml:
analog:
  - { id: pitch_wheel, name: Pitch, pin: PA4, mode: pitch_bend, adc_min: 1420, adc_max: 2360 }
  - { id: mod_wheel, name: Mod, pin: PA5, cc: 1, adc_min: 1420, adc_max: 2360 }
  # reading falls as you press: adc_min (released) is the high end
  - { id: aftertouch, name: Aftertouch, pin: PC3, mode: channel_pressure, adc_min: 2304, adc_max: 1232 }

led_defaults: { idle: blue, active: white }
leds:
  - { id: rec_led, pin: PB12, idle: on }        # lit until pressed
  - { id: b1_led, pin: PB13, pin2: PB14, pin3: PB15, idle: blue, active: white }

buttons:
  - { id: up, pin: PB5, action: preset_next }
  - { id: down, pin: PB6, action: preset_prev }
presets:
  slots: 3
  list:
    - name: Default
    - name: Drums
      program: 9
      midi: { channel: 10 }

analog:
  - { id: fader_1, pin: PA0, cc: 20, daw: volume_1, touch: movement }
buttons:
  - { id: play, pin: PB4, action: cc_momentary, cc: 118, daw: play }
  - { id: back, pin: PB5, action: cc_momentary, cc: 119, daw: nav_back }
  - { id: panic, pin: PB6, action: cc_momentary, cc: 3, daw: zynthian.all_notes_off }

midi_messages:
  null_rpn: true
  sysex:
    - { id: gs_volume, data: "F0 41 10 42 12 [40 00 04 v] cs F7" }
buttons:
  - { id: panic, pin: PB4, action: panic }
  - { id: play, pin: PB5, action: mmc, mmc: play }
  - { id: piano, pin: PB6, action: program, program: 0, bank: { msb: 121, lsb: 0 }, channel: 2 }
analog:
  - { id: fader_1, pin: PA0, mode: cc14, cc: 7 }
  - { id: fader_2, pin: PA1, mode: nrpn14, nrpn: 1234 }
  - { id: volume, pin: PA2, mode: sysex, sysex: gs_volume, min: 0, max: 100 }
encoders:
  - { id: encoder_1, pin_a: PB8, pin_b: PB9, cc: 20, mode: relative_sign }
